    UUID memberB = seedMember();
    seedGrant(accountAId, memberA);
    seedGrant(accountBId, memberB);

    GimbalFixture gimbal = seedGimbalAndLogin(accountAId, 1L);
    String uploaderA = accountAId + ":" + instA;
    String uploaderB = accountBId + ":" + instB;

