@SuppressWarnings("unchecked")
static List<Session> parseSessions(Object raw) {
    if (!(raw instanceof List<?> list)) return new ArrayList<>();
    List<Session> out = new ArrayList<>();
    for (Object item : list) {
        if (item instanceof Map<?,?> m) {
