        List<Session> fresh = new ArrayList<>();
        fresh.add(new Session(sessionId, 1));
        return new Resolution(Relation.FIRST_OR_ADVANCED, 1, prune(fresh));
    }
    Integer known = generationOf(sessions, sessionId);
    int generation;
    if (known != null) {
        generation = known;
    } else {
        generation = maxGeneration(sessions) + 1;
        sessions.add(new Session(sessionId, generation));
    }
    sessions = prune(sessions);
    if (recordedGeneration == null) {
        return new Resolution(Relation.FIRST_OR_ADVANCED, generation, sessions);
    }
    if (generation > recordedGeneration) return new Resolution(Relation.NEWER, generation, sessions);
    if (generation == recordedGeneration) return new Resolution(Relation.SAME, generation, sessions);
    return new Resolution(Relation.STALE, generation, sessions);
}
