private static List<Session> prune(List<Session> sessions) {
    if (sessions.size() <= MAX_TRACKED_SESSIONS) return sessions;
    List<Session> sorted = new ArrayList<>(sessions);
    sorted.sort(Comparator.comparingInt(Session::generation).reversed());
    List<Session> kept = new ArrayList<>(sorted.subList(0, MAX_TRACKED_SESSIONS));
    kept.sort(Comparator.comparingInt(Session::generation));
    return kept;
}
```
